draw:
var rows = [
  ["people", "2.7e6 people"],
  ["divide by 2.5 people per household", "1.1e6 households"],
  ["divide by 20 households per piano", "5.4e4 pianos"],
  ["times 1 tuning per piano per year", "5.4e4 tunings/yr"],
  ["divide by 1000 tunings per tuner per year", "54 tuners"]
];
ctx.font = "12px ui-sans-serif, system-ui, sans-serif";
ctx.textBaseline = "middle";
ctx.lineWidth = 1;

ctx.fillStyle = C.ink;
ctx.textAlign = "left";
ctx.fillText("Fermi chain: each link cancels one unit and hands on the next", 12, 16);

var top = 40;
var gap = (H - top - 16) / rows.length;
var boxW = Math.min(200, W * 0.42);
var bx = W - boxW - 12;

for (var i = 0; i < rows.length; i++) {
  var y = top + gap * i;
  ctx.strokeStyle = i === rows.length - 1 ? C.accent : C.rule;
  ctx.lineWidth = i === rows.length - 1 ? 2 : 1;
  ctx.beginPath();
  ctx.rect(bx, y - 12, boxW, 24);
  ctx.stroke();
  ctx.lineWidth = 1;
  ctx.fillStyle = i === rows.length - 1 ? C.accent : C.ink;
  ctx.textAlign = "center";
  ctx.fillText(rows[i][1], bx + boxW / 2, y);

  if (i > 0) {
    ctx.strokeStyle = C.faint;
    ctx.beginPath();
    ctx.moveTo(bx + boxW / 2, y - 12 - gap + 24);
    ctx.lineTo(bx + boxW / 2, y - 16);
    ctx.stroke();
    ctx.fillStyle = C.figure;
    ctx.beginPath();
    ctx.moveTo(bx + boxW / 2, y - 12);
    ctx.lineTo(bx + boxW / 2 - 4, y - 19);
    ctx.lineTo(bx + boxW / 2 + 4, y - 19);
    ctx.closePath();
    ctx.fill();
    ctx.fillStyle = C.figure;
    ctx.textAlign = "right";
    ctx.fillText(rows[i][0], bx - 12, y - gap / 2);
  }
}
out.note = "";
